const SECRET_KEY=/(token|secret|password|passwd|api[_-]?key|authorization|cookie|private[_-]?key)/i;
const SECRET_VALUE=/(sk-[A-Za-z0-9_-]{12,}|gh[pousr]_[A-Za-z0-9_-]{12,}|bearer\s+[A-Za-z0-9._~+/=-]{12,})/i;
function safe(v){
  if(Array.isArray(v)) return v.map(safe);
  if(v && typeof v==='object'){
    const out={};
    for(const [k,val] of Object.entries(v)) out[k]=SECRET_KEY.test(k)?'[REDACTED]':safe(val);
    return out;
  }
  if(typeof v==='string' && SECRET_VALUE.test(v)) return '[REDACTED_SECRET_LIKE]';
  return v;
}
const raw=$input.first().json || {};
const clean=safe(raw);
const refs=Array.isArray(clean.evidence_refs)?clean.evidence_refs.map(String).slice(0,50):[];
return [{json:{
  schema:'OGENIC_N8N_EVIDENCE_ENVELOPE_V1',
  oge:String(clean.oge||'').slice(0,32),
  source:String(clean.source||'unknown').slice(0,80),
  run_ref:String(clean.run_ref||'').slice(0,240),
  evidence_refs:refs,
  output:clean.output ?? null,
  verification_state:'unverified',
  ruby_verification_required:true,
  green_retention_allowed:false,
  secret_values_included:false,
  control:{execution_authority:'YELLOW_STONE_ONLY',n8n_role:'POSTRUN_NORMALIZER'}
}}];
